<?php
require_once(__DIR__ . '/../../init.php'); require_once(__DIR__ . '/logStats.php'); class med_ambulance_logDispatcher { const LOG_PATH = 'CallLogs'; const LOG_FILE_PREFIX = 'MedCall_'; public function logToCsv($record) { $curDate = new DateTime(); $filename = self::LOG_PATH . '//' . self::LOG_FILE_PREFIX . $curDate->format('Ymd') . '.log'; $record_array = safe_json_decode($record, true); $date = date("d.m.Y H:i:s"); if (!is_dir(getLogPath() . self::LOG_PATH)) { mkdir(getLogPath() . self::LOG_PATH); } $logFiles = glob(getLogPath() . self::LOG_PATH. '//' . self::LOG_FILE_PREFIX . '*.log'); foreach ($logFiles as $key => $logFile) { if (preg_match('#MedCall_(\d{8}).+#', realpath($logFile), $matches)) { $dateFile = new DateTime($matches[1]); $interval = $curDate->diff($dateFile); if ($interval->d >= 7) { unlink(realpath($logFile)); } } } if (!is_file(getLogPath() . $filename)) { $message = 'logDateTime|' . implode('|', array_keys($record_array)); file_put_contents(getLogPath() . $filename, $message); } $message = "\n" . $date .'|' . implode('|', $record_array); file_put_contents(getLogPath() . $filename, $message, FILE_APPEND); } } handleJsonRpc('med_ambulance_logDispatcher'); 